import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import { useAuth } from '../api/AuthContext';

export default function InternshipDetail() {
  const { id } = useParams();
  const [internship, setInternship] = useState(null);
  const [msg, setMsg] = useState({ text: '', type: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { user } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    api.get(`/internships/${id}`)
      .then(r => setInternship(r.data))
      .catch(() => navigate('/internships'));
  }, [id, navigate]);

  // Helper to ensure URLs have http/https prefix
  const getSafeUrl = (url) => {
    if (!url) return '';
    return url.startsWith('http://') || url.startsWith('https://') 
      ? url 
      : `https://${url}`;
  };

  const handleApply = async () => {
    const targetUrl = getSafeUrl(internship.applyUrl);

    // Open new tab immediately to bypass browser popup blockers
    let externalTab = null;
    if (targetUrl) {
      externalTab = window.open('', '_blank');
    }

    setIsSubmitting(true);
    try {
      await api.post(`/applications/apply/${id}`);
      setInternship(prev => ({ 
        ...prev, 
        applied: true, 
        applicantCount: (prev.applicantCount || 0) + 1 
      }));
      setMsg({ text: 'Application recorded successfully!', type: 'success' });

      // Navigate opened tab to the external application page
      if (externalTab && targetUrl) {
        externalTab.location.href = targetUrl;
      }
    } catch (err) {
      if (externalTab) externalTab.close();
      setMsg({ 
        text: err.response?.data?.message || 'Failed to submit application or already applied', 
        type: 'danger' 
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!internship) return <div className="loading">Loading...</div>;

  const validApplyUrl = getSafeUrl(internship.applyUrl);

  return (
    <div className="detail-page">
      <div className="detail-card">
        <h1>{internship.title}</h1>
        <div className="company-name">{internship.company}</div>

        {msg.text && (
          <div className={msg.type === 'success' ? 'success-msg' : 'error-msg'}>
            {msg.text}
          </div>
        )}

        <div className="detail-section">
          <h4>Description</h4>
          <p>{internship.description || 'No description provided.'}</p>
        </div>

        <div className="detail-section">
          <h4>Stipend</h4>
          <p>{internship.stipend || 'Not specified'}</p>
        </div>

        <div className="detail-section">
          <h4>Last Date to Apply</h4>
          <p>{internship.deadline || 'No deadline specified'}</p>
        </div>

        <div className="detail-section">
          <h4>Eligible Departments</h4>
          <div className="tags">
            {internship.eligibleDepartments && internship.eligibleDepartments.length > 0 ? (
              internship.eligibleDepartments.map(d => <span key={d} className="tag">{d}</span>)
            ) : (
              <span className="tag">All Departments</span>
            )}
          </div>
        </div>

        <div className="detail-section">
          <h4>Eligible Batches</h4>
          <div className="tags">
            {internship.eligibleBatches && internship.eligibleBatches.length > 0 ? (
              internship.eligibleBatches.map(b => <span key={b} className="tag tag-batch">{b}</span>)
            ) : (
              <span className="tag tag-batch">All Batches</span>
            )}
          </div>
        </div>

        <div className="detail-section">
          <h4>Total Applicants</h4>
          <p>{internship.applicantCount ?? 0}</p>
        </div>

        <div className="detail-actions">
          {/* Student Actions */}
          {user?.role === 'STUDENT' && (
            internship.applied ? (
              <>
                <span className="badge-applied">✓ Already Applied</span>
                {validApplyUrl && (
                  <a 
                    href={validApplyUrl} 
                    target="_blank" 
                    rel="noreferrer" 
                    className="btn btn-outline-primary"
                  >
                    Open Application Link ↗
                  </a>
                )}
              </>
            ) : internship.eligible ? (
              <button 
                className="btn btn-success" 
                onClick={handleApply}
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Submitting...' : 'Apply Now'}
              </button>
            ) : (
              <span className="badge-ineligible">Not Eligible</span>
            )
          )}

          {/* Admin / Coordinator Actions */}
          {user?.role === 'ADMIN' && validApplyUrl && (
            <a 
              href={validApplyUrl} 
              target="_blank" 
              rel="noreferrer" 
              className="btn btn-primary"
            >
              Open Application Link ↗
            </a>
          )}

          <button className="btn btn-secondary" onClick={() => navigate(-1)}>
            Back
          </button>
        </div>
      </div>
    </div>
  );
}
